//! Generalized linear, categorical-response, nonlinear, PLS, orthogonal and
//! weighted regression against SciPy / scikit-learn references
//! (generated by `tests/gen/glm_ref.py`).

mod common;
use common::glm_data as d;

use openstats_math::dist::{ChiSquared, ContinuousDistribution};
use openstats_math::linalg::Matrix;
use openstats_stats::glm::ordinal::{nominal_logistic, ordinal_logistic, CategoricalOptions};
use openstats_stats::glm::stepwise::{glm_stepwise, GlmStepwiseOptions};
use openstats_stats::glm::{
    association, classification_table, glm, hosmer_lemeshow, roc_curve, Family, GlmOptions, Link,
};
use openstats_stats::model::{Data, DesignOptions};
use openstats_stats::nonlinear::{nonlinear_regression, NonlinearOptions, Parameter};
use openstats_stats::orthogonal::orthogonal_regression;
use openstats_stats::pls::{pls_regression, CrossValidation, PlsOptions};
use openstats_stats::regression::{regress_weighted, RegressionOptions, StepMethod};

fn close(a: f64, b: f64, rel: f64, what: &str) {
    let tol = rel * (1.0 + b.abs());
    assert!((a - b).abs() <= tol, "{what}: {a} vs reference {b} (tol {tol})");
}

fn close_all(a: &[f64], b: &[f64], rel: f64, what: &str) {
    assert_eq!(a.len(), b.len(), "{what}: length");
    for (i, (x, y)) in a.iter().zip(b).enumerate() {
        close(*x, *y, rel, &format!("{what}[{i}]"));
    }
}

fn groups(g: &[f64]) -> Vec<&'static str> {
    g.iter().map(|&v| ["a", "b", "c"][v as usize]).collect()
}

fn logistic_data() -> Data {
    Data::new()
        .with_numeric("y", d::LG_Y.to_vec())
        .unwrap()
        .with_numeric("x1", d::LG_X1.to_vec())
        .unwrap()
        .with_numeric("x2", d::LG_X2.to_vec())
        .unwrap()
        .with_factor("g", &groups(d::LG_G))
        .unwrap()
}

#[test]
fn binary_logistic_matches_sklearn() {
    let data = logistic_data();
    let fit = glm("y ~ x1 + x2 + g", &data, &DesignOptions::default(), &GlmOptions::logistic()).unwrap();
    assert!(fit.converged);
    let est: Vec<f64> = fit.coefficients.iter().map(|c| c.estimate).collect();
    let se: Vec<f64> = fit.coefficients.iter().map(|c| c.std_err).collect();
    close_all(&est, d::LG_COEF, 1e-6, "coef");
    close_all(&se, d::LG_SE, 1e-6, "se");
    close(fit.deviance, d::LG_DEV, 1e-9, "deviance");
    close(fit.null_deviance, d::LG_NULL_DEV, 1e-9, "null deviance");
    close(fit.loglik.unwrap(), d::LG_LL, 1e-9, "loglik");
    close(fit.aic.unwrap(), d::LG_AIC, 1e-9, "aic");
    close(fit.bic.unwrap(), d::LG_BIC, 1e-9, "bic");
    close(fit.pearson_chi2, d::LG_PEARSON_CHI2, 1e-8, "pearson");
    close_all(&fit.fitted, d::LG_FIT, 1e-6, "fitted");
    close_all(&fit.leverage, d::LG_HAT, 1e-5, "hat");
    close_all(&fit.pearson_residuals, d::LG_PEARSON, 1e-5, "pearson residuals");
    close_all(&fit.deviance_residuals, d::LG_DEVRES, 1e-5, "deviance residuals");
    // Odds ratios are exp(coef).
    let or = fit.coefficients[1].ratio.unwrap();
    close(or, d::LG_COEF[1].exp(), 1e-6, "odds ratio");
    assert!(fit.coefficients[0].ratio.is_none());
    // Deviance table: Type III likelihood-ratio tests.
    let row = |name: &str| fit.deviance_table.iter().find(|r| r.source == name).unwrap();
    close(row("x1").deviance, d::LG_X1_ADJDEV, 1e-6, "x1 adj dev");
    close(row("g").deviance, d::LG_G_ADJDEV, 1e-6, "g adj dev");
    assert_eq!(row("g").df, 2);
    let p = ChiSquared::new(1.0).unwrap().sf(d::LG_X1_ADJDEV);
    close(row("x1").p_value.unwrap(), p, 1e-6, "x1 p");
    assert_eq!(row("Regression").df, 4);
    close(row("Total").deviance, d::LG_NULL_DEV, 1e-9, "total");
}

#[test]
fn diagnostics_match_reference() {
    let data = logistic_data();
    let fit = glm("y ~ x1 + x2 + g", &data, &DesignOptions::default(), &GlmOptions::logistic()).unwrap();
    let roc = roc_curve(&fit).unwrap();
    close(roc.auc, d::LG_AUC, 1e-12, "auc");
    assert_eq!((roc.fpr[0], roc.tpr[0]), (0.0, 0.0));
    assert_eq!((*roc.fpr.last().unwrap(), *roc.tpr.last().unwrap()), (1.0, 1.0));
    let a = association(&fit).unwrap();
    close(a.somers_d, 2.0 * d::LG_AUC - 1.0, 1e-12, "somers d");
    close(a.concordant + a.discordant + a.ties, a.pairs, 1e-12, "pairs");
    let c = classification_table(&fit, 0.5).unwrap();
    assert_eq!((c.true_pos, c.false_neg, c.false_pos, c.true_neg), (d::LG_TP, d::LG_FN, d::LG_FP, d::LG_TN));
    let h = hosmer_lemeshow(&fit, 10).unwrap();
    close(h.chi_sq, d::LG_HL_CHI, 1e-8, "hl chi");
    assert_eq!(h.df as f64, d::LG_HL_DF);
    close(h.p_value, d::LG_HL_P, 1e-8, "hl p");
    // The cutoff moves cases between cells but never changes totals.
    let c2 = classification_table(&fit, 0.3).unwrap();
    assert_eq!(c2.true_pos + c2.false_neg, c.true_pos + c.false_neg);
    assert!(c2.sensitivity() >= c.sensitivity());
    // Standardized residuals and Cook's distance are finite and consistent.
    for i in 0..fit.n {
        assert!(fit.cooks_d[i] >= 0.0 && fit.cooks_d[i].is_finite());
        assert!(fit.leverage[i] > 0.0 && fit.leverage[i] < 1.0);
    }
}

#[test]
fn probit_and_cloglog_links() {
    let data = logistic_data();
    for (link, coef, dev) in
        [(Link::Probit, d::LG_PROBIT_COEF, d::LG_PROBIT_DEV), (Link::Cloglog, d::LG_CLL_COEF, d::LG_CLL_DEV)]
    {
        let o = GlmOptions { link, ..GlmOptions::logistic() };
        let fit = glm("y ~ x1 + x2 + g", &data, &DesignOptions::default(), &o).unwrap();
        let est: Vec<f64> = fit.coefficients.iter().map(|c| c.estimate).collect();
        close_all(&est, coef, 1e-5, "coef");
        close(fit.deviance, dev, 1e-8, "deviance");
    }
    // Links that do not suit the family are refused.
    let bad = GlmOptions { link: Link::Log, ..GlmOptions::logistic() };
    assert!(glm("y ~ x1", &data, &DesignOptions::default(), &bad).is_err());
}

#[test]
fn events_and_trials() {
    let data = Data::new()
        .with_numeric("ev", d::EV_EVENTS.to_vec())
        .unwrap()
        .with_numeric("dose", d::EV_DOSE.to_vec())
        .unwrap();
    let o = GlmOptions { trials: Some(d::EV_TRIALS.to_vec()), ..GlmOptions::logistic() };
    let fit = glm("ev ~ dose", &data, &DesignOptions::default(), &o).unwrap();
    let est: Vec<f64> = fit.coefficients.iter().map(|c| c.estimate).collect();
    let se: Vec<f64> = fit.coefficients.iter().map(|c| c.std_err).collect();
    close_all(&est, d::EV_COEF, 1e-6, "coef");
    close_all(&se, d::EV_SE, 1e-6, "se");
    close(fit.deviance, d::EV_DEV, 1e-8, "deviance");
    close(fit.pearson_chi2, d::EV_PEARSON, 1e-6, "pearson"); // sklearn's L-BFGS coefficients are good to ~1e-8
    close(fit.loglik.unwrap(), d::EV_LL, 1e-9, "loglik");
    assert_eq!(fit.df_error, 6);
    let a = association(&fit).unwrap();
    assert!(a.somers_d > 0.5);
    // Trials must cover the events.
    let mut t = d::EV_TRIALS.to_vec();
    t[0] = 1.0;
    let bad = GlmOptions { trials: Some(t), ..GlmOptions::logistic() };
    assert!(glm("ev ~ dose", &data, &DesignOptions::default(), &bad).is_err());
}

fn poisson_data() -> Data {
    Data::new()
        .with_numeric("y", d::PO_Y.to_vec())
        .unwrap()
        .with_numeric("x1", d::PO_X1.to_vec())
        .unwrap()
        .with_numeric("x2", d::PO_X2.to_vec())
        .unwrap()
        .with_numeric("nb", d::NB_Y.to_vec())
        .unwrap()
}

#[test]
fn poisson_matches_sklearn() {
    let fit = glm("y ~ x1 + x2", &poisson_data(), &DesignOptions::default(), &GlmOptions::poisson()).unwrap();
    let est: Vec<f64> = fit.coefficients.iter().map(|c| c.estimate).collect();
    let se: Vec<f64> = fit.coefficients.iter().map(|c| c.std_err).collect();
    close_all(&est, d::PO_COEF, 1e-6, "coef");
    close_all(&se, d::PO_SE, 1e-6, "se");
    close(fit.deviance, d::PO_DEV, 1e-8, "deviance");
    close(fit.null_deviance, d::PO_NULL_DEV, 1e-8, "null deviance");
    close(fit.loglik.unwrap(), d::PO_LL, 1e-9, "loglik");
    close(fit.aic.unwrap(), d::PO_AIC, 1e-9, "aic");
    close(fit.pearson_chi2, d::PO_PEARSON, 1e-8, "pearson");
    close_all(&fit.fitted, d::PO_FIT, 1e-6, "fitted");
    // Rate ratio.
    close(fit.coefficients[1].ratio.unwrap(), d::PO_COEF[1].exp(), 1e-6, "rate ratio");
    // Prediction at new data.
    let newd = Data::new().with_numeric("x1", vec![1.0, 2.0]).unwrap().with_numeric("x2", vec![0.0, -1.0]).unwrap();
    let p = fit.predict(&newd, 0.95).unwrap();
    close(p[0].fit, (d::PO_COEF[0] + d::PO_COEF[1]).exp(), 1e-6, "prediction");
    assert!(p[0].ci.lower < p[0].fit && p[0].fit < p[0].ci.upper);
}

#[test]
fn negative_binomial_matches_scipy_mle() {
    let o = GlmOptions::new(Family::NegativeBinomial);
    let fit = glm("nb ~ x1 + x2", &poisson_data(), &DesignOptions::default(), &o).unwrap();
    let est: Vec<f64> = fit.coefficients.iter().map(|c| c.estimate).collect();
    close_all(&est, d::NB_COEF, 1e-4, "coef");
    close(fit.theta.unwrap().0, d::NB_THETA, 1e-4, "theta");
    close(fit.loglik.unwrap(), d::NB_LL, 1e-8, "loglik");
    // A fixed theta is honoured.
    let o2 = GlmOptions { theta: Some(2.0), ..o };
    let f2 = glm("nb ~ x1 + x2", &poisson_data(), &DesignOptions::default(), &o2).unwrap();
    assert_eq!(f2.theta.unwrap().0, 2.0);
}

#[test]
fn gamma_log_link_matches_scipy() {
    let data = Data::new().with_numeric("y", d::GA_Y.to_vec()).unwrap().with_numeric("x", d::GA_X.to_vec()).unwrap();
    let o = GlmOptions { link: Link::Log, ..GlmOptions::new(Family::Gamma) };
    let fit = glm("y ~ x", &data, &DesignOptions::default(), &o).unwrap();
    let est: Vec<f64> = fit.coefficients.iter().map(|c| c.estimate).collect();
    let se: Vec<f64> = fit.coefficients.iter().map(|c| c.std_err).collect();
    close_all(&est, d::GA_COEF, 1e-6, "coef");
    close(fit.deviance, d::GA_DEV, 1e-7, "deviance");
    close(fit.pearson_chi2, d::GA_PEARSON, 1e-7, "pearson");
    close_all(&se, d::GA_SE, 1e-6, "se");
}

#[test]
fn ordinal_logistic_matches_scipy_mle() {
    let data = Data::new()
        .with_numeric("c", d::OR_CAT.to_vec())
        .unwrap()
        .with_numeric("x1", d::OR_X1.to_vec())
        .unwrap()
        .with_numeric("g", d::OR_G.to_vec())
        .unwrap();
    let labels: Vec<String> = ["1", "2", "3", "4"].iter().map(|s| s.to_string()).collect();
    let fit =
        ordinal_logistic("c ~ x1 + g", &data, &DesignOptions::default(), &CategoricalOptions::new(labels)).unwrap();
    assert!(fit.converged);
    let mut est: Vec<f64> = fit.thresholds.iter().map(|c| c.estimate).collect();
    est.extend(fit.coefficients.iter().map(|c| c.estimate));
    let mut se: Vec<f64> = fit.thresholds.iter().map(|c| c.std_err).collect();
    se.extend(fit.coefficients.iter().map(|c| c.std_err));
    close_all(&est, d::OR_COEF, 1e-5, "estimates");
    close_all(&se, d::OR_SE, 1e-4, "se");
    close(fit.tests.loglik, d::OR_LL, 1e-9, "loglik");
    close(fit.tests.null_loglik, d::OR_NULL_LL, 1e-9, "null loglik");
    assert_eq!(fit.tests.g_df, 2);
    close(fit.tests.g, 2.0 * (d::OR_LL - d::OR_NULL_LL), 1e-8, "G");
    for i in 0..fit.n {
        let s: f64 = (0..4).map(|c| fit.probabilities[(i, c)]).sum();
        close(s, 1.0, 1e-12, "probabilities sum");
    }
    assert!(fit.coefficients[0].odds_ratio.unwrap() > 1.0);
    // Probit link also runs and fits at least as well as the null.
    let labels: Vec<String> = ["1", "2", "3", "4"].iter().map(|s| s.to_string()).collect();
    let o = CategoricalOptions { link: Link::Probit, ..CategoricalOptions::new(labels) };
    let pf = ordinal_logistic("c ~ x1 + g", &data, &DesignOptions::default(), &o).unwrap();
    assert!(pf.tests.g > 0.0);
}

#[test]
fn nominal_logistic_matches_sklearn() {
    let data = Data::new()
        .with_numeric("c", d::NO_CAT.to_vec())
        .unwrap()
        .with_numeric("x1", d::NO_X1.to_vec())
        .unwrap()
        .with_numeric("x2", d::NO_X2.to_vec())
        .unwrap();
    let labels: Vec<String> = ["A", "B", "C"].iter().map(|s| s.to_string()).collect();
    let fit =
        nominal_logistic("c ~ x1 + x2", &data, &DesignOptions::default(), &CategoricalOptions::new(labels)).unwrap();
    assert!(fit.converged);
    let est: Vec<f64> = fit.logits.iter().flat_map(|(_, r)| r.iter().map(|c| c.estimate)).collect();
    let se: Vec<f64> = fit.logits.iter().flat_map(|(_, r)| r.iter().map(|c| c.std_err)).collect();
    close_all(&est, d::NO_COEF, 1e-5, "coef");
    close_all(&se, d::NO_SE, 1e-5, "se");
    close(fit.tests.loglik, d::NO_LL, 1e-9, "loglik");
    close(fit.tests.null_loglik, d::NO_NULL_LL, 1e-9, "null loglik");
    assert_eq!(fit.tests.g_df, 4);
    let probs: Vec<f64> =
        (0..fit.n).flat_map(|i| (0..3).map(move |c| (i, c))).map(|(i, c)| fit.probabilities[(i, c)]).collect();
    close_all(&probs, d::NO_PROB, 1e-6, "probabilities");
    // Prediction at the first rows reproduces the stored probabilities.
    let (rows, p) = fit.predict(&data).unwrap();
    assert_eq!(rows.len(), fit.n);
    close(p[(0, 1)], fit.probabilities[(0, 1)], 1e-12, "predict");
    // A different reference category is a reparameterization: same likelihood.
    let labels: Vec<String> = ["A", "B", "C"].iter().map(|s| s.to_string()).collect();
    let o = CategoricalOptions { reference: 2, ..CategoricalOptions::new(labels) };
    let f2 = nominal_logistic("c ~ x1 + x2", &data, &DesignOptions::default(), &o).unwrap();
    close(f2.tests.loglik, d::NO_LL, 1e-9, "reference-free loglik");
}

#[test]
fn nonlinear_curve_fit_matches_scipy() {
    let data = Data::new().with_numeric("y", d::NL_Y.to_vec()).unwrap().with_numeric("x", d::NL_X.to_vec()).unwrap();
    let params = [Parameter::new("a", 2.0), Parameter::new("b", 0.3), Parameter::new("c", 0.0)];
    let fit = nonlinear_regression("y", "y = a*exp(-b*x) + c", &params, &data, &NonlinearOptions::default()).unwrap();
    assert!(fit.converged);
    close_all(&fit.estimates(), d::NL_PAR, 1e-6, "params");
    let se: Vec<f64> = fit.coefficients.iter().map(|c| c.std_err).collect();
    close_all(&se, d::NL_SE, 1e-4, "se");
    close(fit.sse, d::NL_SSE, 1e-9, "sse");
    assert_eq!(fit.df_error, 27);
    // The correlation matrix has unit diagonal.
    for j in 0..3 {
        close(fit.correlation[(j, j)], 1.0, 1e-12, "corr diag");
    }
}

#[test]
fn michaelis_menten_bounds_and_prediction() {
    let data = Data::new().with_numeric("v", d::MM_Y.to_vec()).unwrap().with_numeric("s", d::MM_X.to_vec()).unwrap();
    let params = [Parameter::new("vmax", 8.0), Parameter::new("km", 2.0)];
    let fit = nonlinear_regression("v", "vmax*s/(km+s)", &params, &data, &NonlinearOptions::default()).unwrap();
    close_all(&fit.estimates(), d::MM_PAR, 1e-6, "params");
    let se: Vec<f64> = fit.coefficients.iter().map(|c| c.std_err).collect();
    close_all(&se, d::MM_SE, 1e-4, "se");
    close(fit.sse, d::MM_SSE, 1e-9, "sse");
    let newd = Data::new().with_numeric("s", vec![10.0]).unwrap();
    let p = fit.predict(&newd, 0.95).unwrap();
    close(p[0].fit, d::MM_PRED, 1e-6, "prediction");
    close(p[0].se_fit, d::MM_PRED_SE, 1e-4, "se fit");
    close(p[0].pi.upper - p[0].fit, d::MM_PRED_PI_HALF, 1e-4, "pi half-width");
    // Bounded fit: Vmax <= 10 (the unconstrained estimate is above it).
    let bounded = [Parameter { upper: Some(10.0), ..Parameter::new("vmax", 8.0) }, Parameter::new("km", 2.0)];
    let bf = nonlinear_regression("v", "vmax*s/(km+s)", &bounded, &data, &NonlinearOptions::default()).unwrap();
    close_all(&bf.estimates(), d::MM_BOUNDED, 1e-4, "bounded params");
    assert!(bf.at_bound.contains(&"vmax".to_string()));
    // Errors: unknown column, bad start.
    assert!(nonlinear_regression("v", "vmax*q/(km+q)", &params, &data, &NonlinearOptions::default()).is_err());
    let out = [Parameter { lower: Some(9.0), ..Parameter::new("vmax", 8.0) }, Parameter::new("km", 2.0)];
    assert!(nonlinear_regression("v", "vmax*s/(km+s)", &out, &data, &NonlinearOptions::default()).is_err());
}

fn pls_cols() -> Vec<(&'static str, &'static [f64])> {
    vec![("x1", d::PLS_X1), ("x2", d::PLS_X2), ("x3", d::PLS_X3), ("x4", d::PLS_X4), ("x5", d::PLS_X5)]
}

#[test]
fn pls_matches_sklearn() {
    for (tag, ys, scale, fit_ref, coef_ref, icpt_ref, tt_ref, press_ref, xvar_ref) in [
        (
            "A",
            vec![("y1", d::PLS_Y1)],
            false,
            d::PLS_A_FIT,
            d::PLS_A_COEF,
            d::PLS_A_ICPT,
            d::PLS_A_TT,
            d::PLS_A_PRESS,
            d::PLS_A_XVAR,
        ),
        (
            "B",
            vec![("y1", d::PLS_Y1), ("y2", d::PLS_Y2)],
            true,
            d::PLS_B_FIT,
            d::PLS_B_COEF,
            d::PLS_B_ICPT,
            d::PLS_B_TT,
            d::PLS_B_PRESS,
            d::PLS_B_XVAR,
        ),
    ] {
        let o = PlsOptions { components: 3, standardize: scale, cv: CrossValidation::LeaveOneOut };
        let fit = pls_regression(&pls_cols(), &ys, &o).unwrap();
        assert_eq!(fit.n_components, 3, "{tag}");
        let q = ys.len();
        let fitted: Vec<f64> =
            (0..fit.n).flat_map(|i| (0..q).map(move |k| (i, k))).map(|(i, k)| fit.fitted[(i, k)]).collect();
        close_all(&fitted, fit_ref, 1e-6, &format!("{tag} fitted"));
        let coef: Vec<f64> =
            (0..5).flat_map(|j| (0..q).map(move |k| (j, k))).map(|(j, k)| fit.coefficients[(j, k)]).collect();
        close_all(&coef, coef_ref, 1e-6, &format!("{tag} coef"));
        close_all(&fit.intercepts, icpt_ref, 1e-6, &format!("{tag} intercept"));
        let tt: Vec<f64> = (0..3).map(|c| fit.x_scores.col(c).iter().map(|v| v * v).sum()).collect();
        close_all(&tt, tt_ref, 1e-6, &format!("{tag} score ss"));
        for c in 0..3 {
            let press = fit.selection[c].press.as_ref().unwrap();
            close_all(press, &press_ref[c * q..(c + 1) * q], 1e-5, &format!("{tag} press {c}"));
            close(fit.selection[c].x_variance, xvar_ref[c], 1e-6, &format!("{tag} x variance {c}"));
        }
        assert!(fit.best_by_press.unwrap() >= 1);
        assert_eq!(fit.vip.len(), 5);
        // VIP² averages to 1.
        let mean_sq = fit.vip.iter().map(|v| v * v).sum::<f64>() / 5.0;
        close(mean_sq, 1.0, 1e-9, "vip");
    }
    // Prediction reproduces the fitted values.
    let fit =
        pls_regression(&pls_cols(), &[("y1", d::PLS_Y1)], &PlsOptions { components: 2, ..Default::default() }).unwrap();
    let xn = Matrix::from_fn(fit.n, 5, |i, j| pls_cols()[j].1[i]);
    let pred = fit.predict(&xn).unwrap();
    close(pred[(3, 0)], fit.fitted[(3, 0)], 1e-12, "predict");
    // k-fold CV yields PRESS too; an excess component request is capped.
    let kf = pls_regression(
        &pls_cols(),
        &[("y1", d::PLS_Y1)],
        &PlsOptions { components: 9, standardize: false, cv: CrossValidation::KFold(5) },
    )
    .unwrap();
    assert_eq!(kf.n_components, 5);
    assert!(kf.selection[0].press.is_some());
}

#[test]
fn orthogonal_regression_matches_scipy_odr() {
    for (delta, slope, icpt) in
        [(d::OD_1_DELTA, d::OD_1_SLOPE, d::OD_1_ICPT), (d::OD_2_DELTA, d::OD_2_SLOPE, d::OD_2_ICPT)]
    {
        let f = orthogonal_regression("x", d::OD_X, "y", d::OD_Y, delta, 0.95).unwrap();
        close(f.slope, slope, 1e-6, "slope");
        close(f.intercept, icpt, 1e-6, "intercept");
        assert!(f.se_slope > 0.0 && f.ci_slope.lower < f.slope && f.slope < f.ci_slope.upper);
    }
    assert!(orthogonal_regression("x", d::OD_X, "y", d::OD_Y, -1.0, 0.95).is_err());
}

#[test]
fn weighted_regression_matches_numpy() {
    let data = Data::new().with_numeric("y", d::WL_Y.to_vec()).unwrap().with_numeric("x", d::WL_X.to_vec()).unwrap();
    let fit =
        regress_weighted("y ~ x", &data, &DesignOptions::default(), d::WL_W, &RegressionOptions::default()).unwrap();
    let est: Vec<f64> = fit.coefficients.iter().map(|c| c.estimate).collect();
    let se: Vec<f64> = fit.coefficients.iter().map(|c| c.std_err).collect();
    close_all(&est, d::WL_COEF, 1e-9, "coef");
    close_all(&se, d::WL_SE, 1e-9, "se");
    close(fit.sse, d::WL_SSE, 1e-9, "sse");
    close(fit.sst, d::WL_SST, 1e-9, "sst");
    close(fit.r2, d::WL_R2, 1e-9, "r2");
    close(fit.f.unwrap(), d::WL_F, 1e-8, "F");
    assert_eq!(fit.df_error, 28);
    // Residuals are on the response scale.
    close(fit.diagnostics.residuals[0], d::WL_Y[0] - (d::WL_COEF[0] + d::WL_COEF[1] * d::WL_X[0]), 1e-9, "residual");
    // Non-positive weights are refused.
    let mut w = d::WL_W.to_vec();
    w[2] = 0.0;
    assert!(regress_weighted("y ~ x", &data, &DesignOptions::default(), &w, &RegressionOptions::default()).is_err());
}

#[test]
fn glm_stepwise_is_consistent_with_the_deviance_table() {
    let data = logistic_data();
    let full = glm("y ~ x1 + x2 + g", &data, &DesignOptions::default(), &GlmOptions::logistic()).unwrap();
    // Backward elimination at a lenient threshold keeps every term of the full model.
    let mut so = GlmStepwiseOptions::new(StepMethod::Backward);
    so.alpha_remove = 0.99;
    let r = glm_stepwise("y ~ x1 + x2 + g", &data, &DesignOptions::default(), &GlmOptions::logistic(), &so).unwrap();
    assert!(r.steps.is_empty());
    close(r.fit.deviance, full.deviance, 1e-9, "kept model deviance");
    // Forward selection adds terms in order of the likelihood-ratio p-value.
    let so = GlmStepwiseOptions::new(StepMethod::Forward);
    let f = glm_stepwise("y ~ x1 + x2 + g", &data, &DesignOptions::default(), &GlmOptions::logistic(), &so).unwrap();
    assert!(!f.steps.is_empty());
    assert!(f.steps[0].p_value <= so.alpha_enter);
    assert!(f.selected.contains(&"x1".to_string()));
    // The final fit equals fitting the selected formula directly.
    let formula = format!("y ~ {}", f.selected.join(" + "));
    let direct = glm(&formula, &data, &DesignOptions::default(), &GlmOptions::logistic()).unwrap();
    close(f.fit.deviance, direct.deviance, 1e-9, "selected deviance");
    // A forced term is never removed.
    let mut so = GlmStepwiseOptions::new(StepMethod::Stepwise);
    so.force_in = vec!["x2".into()];
    so.alpha_enter = 0.0001;
    let s = glm_stepwise("y ~ x1 + x2 + g", &data, &DesignOptions::default(), &GlmOptions::logistic(), &so).unwrap();
    assert!(s.selected.contains(&"x2".to_string()));
}

#[test]
fn responses_outside_the_family_are_rejected() {
    let data = logistic_data();
    // x1 contains negative, non-integer values: not a count and not binary.
    assert!(glm("x1 ~ x2", &data, &DesignOptions::default(), &GlmOptions::poisson()).is_err());
    assert!(glm("x1 ~ x2", &data, &DesignOptions::default(), &GlmOptions::logistic()).is_err());
    let o = GlmOptions::new(Family::Gamma);
    assert!(glm("x1 ~ x2", &data, &DesignOptions::default(), &o).is_err());
}
